source = '''from collections import Counter


def _runs(values, color):
    runs = []
    start = None
    for i, value in enumerate(list(values) + [None]):
        if value == color:
            if start is None:
                start = i
        elif start is not None:
            runs.append((start, i - 1))
            start = None
    return runs


def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(value for row in grid for value in row)
    background = counts.most_common(1)[0][0]

    sides = {
        "top": grid[0],
        "bottom": grid[-1],
        "left": [row[0] for row in grid],
        "right": [row[-1] for row in grid],
    }
    candidates = []
    for axis, side_a, side_b in (("h", "top", "bottom"), ("v", "left", "right")):
        colors = set(sides[side_a]) & set(sides[side_b])
        for color in colors - {background}:
            for a0, a1 in _runs(sides[side_a], color):
                for b0, b1 in _runs(sides[side_b], color):
                    score = (a1 - a0 + 1) + (b1 - b0 + 1)
                    candidates.append((score, axis, side_a, side_b, color, (a0, a1), (b0, b1)))
    if not candidates:
        return [row[:] for row in grid]
    _, axis, side_a, side_b, bar, run_a, run_b = max(candidates, key=lambda x: x[0])
    out = [row[:] for row in grid]
    seed_colors = {value for row in grid for value in row if value not in (background, bar)}
    if not seed_colors:
        return out

    if axis == "h":
        tangent = lambda r, c: c
        normal = lambda r, c: r
        side_pos = {"top": 0, "bottom": h - 1}
        tangent_len = w
    else:
        tangent = lambda r, c: r
        normal = lambda r, c: c
        side_pos = {"left": 0, "right": w - 1}
        tangent_len = h

    runs = {side_a: run_a, side_b: run_b}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color not in seed_colors:
                continue
            t = tangent(r, c)
            possible = [(side, run) for side, run in runs.items() if run[0] <= t <= run[1]]
            if not possible:
                continue
            # Use the boundary segment nearest this seed as its source.
            src_side, src_run = min(possible, key=lambda item: abs(normal(r, c) - side_pos[item[0]]))
            boundary = side_pos[src_side]
            n = normal(r, c)
            if n == boundary:
                continue
            step = 1 if n > boundary else -1
            for q in range(boundary + step, n, step):
                rr, cc = (q, c) if axis == "h" else (r, q)
                if grid[rr][cc] != bar:
                    out[rr][cc] = color
            out[r][c] = 4

            # The matching position on the opposite border casts the full ray.
            dst_side = side_b if src_side == side_a else side_a
            dst_run = runs[dst_side]
            offset = t - src_run[0]
            target_t = dst_run[0] + offset
            if not (dst_run[0] <= target_t <= dst_run[1]):
                continue
            target_n = side_pos[dst_side]
            step = -1 if target_n == 0 else 1
            for q in range(target_n + step, (h if axis == "h" else w) if step > 0 else -1, step):
                rr, cc = (q, target_t) if axis == "h" else (target_t, q)
                if grid[rr][cc] != bar:
                    out[rr][cc] = color
    return out
'''
